"""Russian report section for the independent cache benchmark and the range replay."""


def add_systems(w):
    w.page("Удержание памяти", "Повтор исходного опыта S3-FIFO",
           "На полной недельной трассе hm_0 мы воспроизвели все три проверенные строки публикации SOSP 2023. На будущей части трассы адаптивное кэширование оказалось эффективнее фиксированного набора частых объектов.")
    w.p("Оригинальный симулятор авторов обработал 3 993 316 обращений MSR Cambridge. Кэш вмещал 43 918 из 439 187 объектов. Сохранены опубликованные идентификаторы, порядок обращений и метрика доли промахов при единичном размере объекта. В третьей колонке показана отдельная оценка на последних 3 194 653 обращениях после общей истории для выбора памяти.")
    w.tbl(["Метод", "Полная трасса", "Будущие 80%"],
          [["S3-FIFO, артефакт 2023", "28,91%", "30,30%"],
           ["ARC, тот же артефакт", "28,91%", "30,46%"],
           ["LRU, тот же артефакт", "31,88%", "33,78%"],
           ["S4-FIFO, предиктор lite 2026", "29,08%", "30,80%"],
           ["Статические частые объекты", "—", "36,24%"],
           ["Выбор доли закрепления", "—", "30,35%"]], small=True)
    w.p("Для первых трёх строк полный повтор совпал с таблицей авторов до её последнего знака. В задаче с одним объектом на обращение совместная цена сводится к частоте. На валидации варианты с 0%, 50% и 100% закреплённых мест дали 78 040, 78 792 и 89 040 промахов. Выбор пал на ноль, и гибрид повторил результат Python-реализации S3-FIFO.")
    w.p("Для S4-FIFO мы соединили оригинальный симулятор с компактным предиктором LightGBM из выпущенного авторами CacheLib. Он выбрал конфигурацию по первой пятой части потока. Авторы включили hm_0 в список обучения предиктора. Полный набор симуляций S4-FIFO охватывает больше трасс.")
    w.source("Таблица SOSP 2023 для hm_0", "https://github.com/Thesys-lab/sosp23-s3fifo/blob/79fde46c03180b95b1091249a6f140282aeae333/result/cachesim/MSR/hm_0.IQI.bin.txt")
    w.source("Артефакт S4-FIFO и предиктор", "https://github.com/cacheMon/osdi26-s4-fifo/tree/000095fc3c96a95ff1b9a19d101fb1411c7f4d54")

    w.page("Удержание памяти", "Что даёт учёт совместных чтений",
           "На 212 992 реальных запросах учёт совместного доступа сэкономил 1,57% чтений относительно статической частоты. Адаптивные S3-FIFO и S4-FIFO остались на сопоставимом уровне.")
    w.p("Взяли первые 32 768 операций чтения с тома 0 каждого из 13 серверов. Первая половина служила для обучения и валидации. На второй сравнивались одинаковые кэши по 512 страниц. Из трассы взяты диапазоны байтов. Наш интерфейс задаёт страницу 4 КиБ и один оплачиваемый вызов на блок 16 КиБ, если хотя бы одной затребованной страницы этого блока нет в кэше.")
    w.tbl(["Политика", "Чтений на запрос", "С начальной загрузкой¹"],
          [["Статическая частота", "1,90166", "1,91797"],
           ["Статическая совместная цена", "1,87185", "1,88878"],
           ["S3-FIFO авторов, Python", "1,86402", "1,86402"],
           ["S4-FIFO с предиктором lite", "1,87123", "1,87123"],
           ["Половина по совместной цене + S3", "1,85498", "1,86494"],
           ["Доля по валидации, совместная цена", "1,86857", "1,87605"]], small=True)
    w.p("¹ Разовое заполнение закреплённых страниц оценено одним вызовом на каждый их исходный блок и распределено на 16 384 тестовых запроса тома. Динамические политики прогреты на той же истории. Время построения и служебная память исключены из обеих колонок.")
    w.p("Разность «частота минус совместная цена» равна 0,02981 чтения, парный 95% бутстреп-интервал по серверам 0,00945–0,05568. Улучшение наблюдалось на 10 томах, равенство на двух, ухудшение на одном. Для гибрида с выбором доли разность «S4 минус гибрид» составила 0,00266 с интервалом от −0,03422 до 0,03088.")
    w.p("На 708 874 чтениях из второй половины полной недели hm_0 совместная политика дала 1,07083 вызова, частота 1,07394, S3 1,05936 и S4 1,06237. Исходные запросы описывают диски одного центра в 2007 году. Для переноса вывода на языковых агентов требуется измерить обращения к их инструментам и качество решений.")
    w.source("Происхождение и формат MSR Cambridge", "https://github.com/cacheMon/cache_dataset/blob/1e53a27824a406b10948699d5eba4c40def90c11/README.md#msr-cambridge-traces")
